  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  assert.equal(result[0].rate, 21);
  // discount = roundCents(996 * 10 / 100) = roundCents(99.6) = 100
  // base = 996 - 100 = 896
  assert.equal(result[0].base, 896);
});

test('vatSummary: handles tier discounts', () => {
  // C-001 is gold tier with 5% discount
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PHOTO-LIC', qty: 1 }, // No explicit discount, gets 5% tier discount
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  // base = 996 * 95% = 946.2 → 946
  assert.equal(result[0].base, 946);
  // VAT = 946 * 21 / 100 = 198.66 → 199
  assert.equal(result[0].vat, 199);
