test('vatSummary: multiple lines with same VAT rate', () => {
  const created = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [
      { sku: 'PHOTO-LIC', qty: 2 },
      { sku: 'FONT-LIC', qty: 1 },
    ],
  });
  const invoice = issueInvoice(created.value, []).value;
  const result = vatSummary([invoice]);
  // PHOTO-LIC: 996 * 2 = 1992 with 5% discount (C-001 gold)
  // Discount = roundCents(1992 * 5 / 100) = roundCents(99.6) = 100
  // Base = 1992 - 100 = 1892
  // FONT-LIC: 1010 * 1 = 1010 with 5% discount
  // Discount = roundCents(1010 * 5 / 100) = roundCents(50.5) = 50 (banker's rounding)
  // Base = 1010 - 50 = 960
  // Total base at 21%: 1892 + 960 = 2852
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 2852);
});

