  const inv2 = createIssuedInvoice('C-002', '2026-10-01'); // standard 0% discount
  const result = vatSummary([inv1, inv2]);
  assert.equal(result.length, 1);
  // C-001: 996 * 95% = 946.2 → 946 (with 5% tier discount)
  // C-002: 996 * 100% = 996 (with 0% tier discount)
  assert.equal(result[0].base, 946 + 996);
});

